class Solution {
public:
    int maxTransactions(vector<int>& transactions) {
        long long bal = 0;
        int cnt = 0;
        priority_queue<int, vector<int>, greater<int>> h;
        for (int t : transactions) {
            bal += t;
            h.push(t);
            cnt++;
            if (bal < 0) {
                bal -= h.top();
                h.pop();
                cnt--;
            }
        }
        return cnt;
    }
};

