class Solution {
    public int maxTransactions(int[] transactions) {
        long bal = 0;
        int cnt = 0;
        PriorityQueue<Long> h = new PriorityQueue<>();
        for (int t : transactions) {
            bal += t;
            h.add((long) t);
            cnt++;
            if (bal < 0) {
                bal -= h.poll();
                cnt--;
            }
        }
        return cnt;
    }
}

