var maxTransactions = function(transactions) {
    const h = [];
    const push = v => {
        h.push(v);
        let i = h.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (h[p] <= h[i]) break;
            [h[p], h[i]] = [h[i], h[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = h[0], last = h.pop();
        if (h.length) {
            h[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < h.length && h[l] < h[m]) m = l;
                if (r < h.length && h[r] < h[m]) m = r;
                if (m === i) break;
                [h[m], h[i]] = [h[i], h[m]];
                i = m;
            }
        }
        return top;
    };
    let bal = 0, cnt = 0;
    for (const t of transactions) {
        bal += t;
        push(t);
        cnt++;
        if (bal < 0) {
            bal -= pop();
            cnt--;
        }
    }
    return cnt;
};
